// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract FixedAuction is Pausable, Ownable {
    struct Auction { uint256 tokenId; bool settled; }
    Auction public auction;
    IERC721 public token;
    bool public initialized;

    function _createAuction() private {
        (bool success, bytes memory data) = address(token).call(abi.encodeWithSignature("mint()"));
        if (!success) {
            _pause(); // explicit revert check, no catch-all
        }
        // decode tokenId from data
    }

    function unpause() external onlyOwner {
        _unpause();
        if (!initialized) {
            initialized = true;
            _createAuction();
        } else if (auction.settled) {
            _createAuction();
        }
    }

    function removeFollower(uint256 followTokenId) external whenNotPaused {
        _unfollowIfHasFollower(followTokenId);
    }

    function _unfollowIfHasFollower(uint256) internal {}
}
